StarterButtons: FC<StarterButtonsProps> = ({
  starters,
  onSelect,
  isMobile,
  isCollapsible = true,
  labels,
  styles,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const pillRefs = useRef<(HTMLDivElement | null)[]>([]);
  const pillWidthCacheRef = useRef<number[]>([]);

  const [visibleCount, setVisibleCount] = useState(() =>
    Math.min(starters.length, MAX_VISIBLE),
  );

  const computeVisibleCount = useCallback(
    (totalStarters: number) => {
      const container = containerRef.current;
      if (!container || !isCollapsible) return;

      const containerWidth = container.getBoundingClientRect().width;
      if (containerWidth === 0) return;

      const cap = Math.min(totalStarters, MAX_VISIBLE);
      const allMounted = pillRefs.current
        .slice(0, cap)
        .every((el) => el != null);
      if (allMounted) {
        pillWidthCacheRef.current = pillRefs.current
          .slice(0, cap)
          .map((el) => el?.getBoundingClientRect().width ?? 0);
      }

      const widthOf = (i: number) => pillWidthCacheRef.current[i] ?? 120;

      let usedWidth = 0;
      let count = 0;

      for (let i = 0; i < cap; i++) {
        const pillWidth = widthOf(i);
        const remainingAfterThis = totalStarters - (i + 1);
        const needsOverflow = remainingAfterThis > 0;
        const projectedWidth =
          usedWidth +
          (i > 0 ? GAP : 0) +
          pillWidth +
          (needsOverflow ? GAP + OVERFLOW_BUTTON_WIDTH : 0);

        if (projectedWidth > containerWidth) break;

        usedWidth += (i > 0 ? GAP : 0) + pillWidth;
        count = i + 1;
      }

      setVisibleCount(Math.max(1, count));
    },
    [isCollapsible],
  );

  useEffect(() => {
    pillWidthCacheRef.current = [];
    setVisibleCount(Math.min(starters.length, MAX_VISIBLE));
  }, [starters.length]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isCollapsible) return;

    const observer = new ResizeObserver(() => {
      computeVisibleCount(starters.length);
    });

    observer.observe(container);

    return () => observer.disconnect();
  }, [computeVisibleCount, isCollapsible, starters.length]);

  /* Re-measure once the newly rendered pill set is mounted: the width cache is
   * only refreshed when every pill up to the cap has a live ref, which is not
   * the case on the render that collapsed them. Converges because a repeated
   * count does not re-render. */
  useEffect(() => {
    computeVisibleCount(starters.length);
  }, [computeVisibleCount, starters.length, visibleCount]);

  const iconProps = useMemo(() => {
    return {
      ...BASE_MD_ICON_PROPS,
      stroke: styles?.iconStrokeWidth ?? BASE_MD_ICON_PROPS.stroke,
      size: styles?.iconSize ?? BASE_MD_ICON_PROPS.size,
    };
  }, [styles?.iconStrokeWidth, styles?.iconSize]);

  if (starters.length === 0) return null;

  const visibleStarters = isCollapsible
    ? starters.slice(0, visibleCount)
    : starters;
  const overflowStarters = isCollapsible ? starters.slice(visibleCount) : [];

  const overflowItems: DropdownItem[] = overflowStarters.map(
    (starter, idx) => ({
      key: String(idx),
      label: starter.title,
      onClick: () => onSelect(starter),
    }),
  );

  return (
    <div
      ref={containerRef}
      className={mergeClasses('mb-4 w-full', STARTER_BUTTONS_CLASS.root)}
    >
      <div
        role="list"
        aria-label={labels.list}
        className={mergeClasses(
          isCollapsible
            ? 'flex flex-wrap justify-center gap-2'
            : 'flex flex-col items-center gap-2',
          STARTER_BUTTONS_CLASS.list,
        )}
      >
        {visibleStarters.map((starter, index) => (
          <div
            key={starter.const}
            role="listitem"
            ref={(el) => {
              pillRefs.current[index] = el;
            }}
          >
            <NeutralButton
              label={starter.title}
              appearance={ButtonAppearance.Outlined}
              onClick={() => onSelect(starter)}
            />
          </div>
        ))}

        {overflowStarters.length > 0 && (
          <div role="listitem">
            <Dropdown
              items={overflowItems}
              placement="bottom-end"
              matchReferenceWidth={false}
            >
              <NeutralIconButton
                appearance={ButtonAppearance.Outlined}
                icon={
                  isMobile ? (
                    <IconDots {...iconProps} stroke={DIAL_KIT_ICON_STROKE} />
                  ) : (
                    <IconDotsVertical
                      {...iconProps}
                      stroke={DIAL_KIT_ICON_STROKE}
                    />
                  )
                }
                aria-label={labels.overflow}
              />
            </Dropdown>
          </div>
        )}
      </div>
    </div>
  );
}

export interface StarterButtonsProps {
  /** Starter prompt options to display as buttons. */
  starters: StarterOption[];
  /** Called when the user selects a starter option. */
  onSelect: (starter: StarterOption) => void;
  /** When `true`, renders a mobile-optimised layout. */
  isMobile?: boolean;
  /**
   * When `true` (the default), only as many starters as the measured
   * container width allows stay on one row and the rest collapse into an
   * overflow dropdown. When `false`, every starter is rendered, each on its
   * own row, and no overflow menu appears.
   */
  isCollapsible?: boolean;
  /** Localized labels used within the component. */
  labels: StarterButtonsLabels;
  /** Optional style overrides. */
  styles?: StarterButtonsStyles;
}

export interface StarterButtonsLabels {
  /** Accessible label (`aria-label`) for the visible buttons list. */
  list: string;
  /** Accessible label (`aria-label`) for the overflow menu button. */
  overflow: string;
}

export interface StarterButtonsStyles {
  /** Icon size in px for the overflow menu icon. Defaults to `BASE_MD_ICON_PROPS.size`. */
  iconSize?: number;
  /** Stroke width for the overflow menu icon. Defaults to `BASE_MD_ICON_PROPS.stroke`. */
  iconStrokeWidth?: number;
}

STARTER_BUTTONS_CLASS = {
  /** The component's outer wrapper. */
  root: 'dial-starter-buttons-root',
  /** The `role="list"` box holding the buttons, in both layouts. */
  list: 'dial-starter-buttons-list',
} as const

